import io
from rich.file_proxy import FileProxy
from rich.console import Console

class MockFile(io.TextIOBase):
    def isatty(self):
        return True
    def fileno(self):
        return 1
    def write(self, s):
        return len(s)

def test_isatty():
    console = Console()
    mock_file = MockFile()
    proxy = FileProxy(console, mock_file)
    print(f"MockFile isatty: {mock_file.isatty()}")
    print(f"FileProxy isatty: {proxy.isatty()}")
    assert proxy.isatty() == mock_file.isatty()

if __name__ == "__main__":
    try:
        test_isatty()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")

