import io
from rich.file_proxy import FileProxy
from rich.console import Console

class MockFile(io.TextIOBase):
    def __init__(self):
        self.closed = False
    def close(self):
        self.closed = True
        return None
    def isatty(self):
        return True
    def fileno(self):
        return 1
    def write(self, s):
        return len(s)

def test_close():
    console = Console()
    mock_file = MockFile()
    proxy = FileProxy(console, mock_file)
    proxy.close()
    print(f"MockFile closed: {mock_file.closed}")
    assert mock_file.closed == True

if __name__ == "__main__":
    try:
        test_close()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")

